export const DICTS: Record<Lang, Dict> = {
  en,
  pt,
  es,
  fr,
  de,
  it,
  pl,
  zh,
  ja,
  ru,
};

const STORAGE_KEY = "chimera.lang";

function detectLang(): Lang {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored && stored in DICTS) return stored as Lang;
  const nav = (navigator.language || "en").slice(0, 2).toLowerCase();
  return (nav in DICTS ? nav : "en") as Lang;
}

/** Substitute `{name}` placeholders from `params`. */
function interpolate(
  template: string,
  params?: Record<string, string | number>,
): string {
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (_, k: string) =>
    k in params ? String(params[k]) : `{${k}}`,
  );
}

export type TFunc = (
  key: string,
  params?: Record<string, string | number>,
) => string;

interface I18nValue {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: TFunc;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(detectLang);

  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  const setLang = useCallback((l: Lang) => {
    localStorage.setItem(STORAGE_KEY, l);
    setLangState(l);
  }, []);

  const t = useCallback<TFunc>(
    (key, params) => {
      const table = DICTS[lang] ?? en;
      const template = table[key] ?? en[key] ?? key;
      return interpolate(template, params);
    },
    [lang],
  );

  const value = useMemo<I18nValue>(
    () => ({ lang, setLang, t }),
    [lang, setLang, t],
  );
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n must be used within I18nProvider");
  return ctx;
}

/** Convenience: just the `t` function. */
export function useT(): TFunc {
  return useI18n().t;
}

/** Group digits the way the CHOSEN language does, not the way the machine does.
 *
 *  `Number.toLocaleString()` with no argument follows the operating system. On a pt-BR machine with
 *  the app set to English that renders 4200 as "4.200", and the English sentence around it —
 *  "4.200 tokens saved across 3 delegated runs" — reads as four point two. A thousandfold misread,
 *  in the one place a number is the whole content.
 *
 *  The formatter is memoised per language rather than built per call: these render inside lists that
 *  can hold hundreds of rows, and `Intl.NumberFormat` construction is the expensive half.
 */
export function useNum(): (n: number) => string {
  const { lang } = useI18n();
  return useMemo(() => {
    const fmt = new Intl.NumberFormat(lang);
    return (n: number) => fmt.format(n);
  }, [lang]);
}

/** A probability, to two decimals, in the CHOSEN language — `0.80` in English, `0,80` in Portuguese.
 *
 *  Separate from `useNum` because the two answer different questions and only one of them is a
 *  formatting choice. `useNum` groups an integer the way the reader's language groups digits;
 *  this fixes the PRECISION as well, and the precision is a decision about the number rather than
 *  about the language: the calibration map's own resolution is coarser than two decimals, and
 *  `0.8000000000000001` on a card reads as a precision the number does not have.
 *
 *  `toFixed(2)` would be one line and would print `0.80` on a pt-BR machine inside a Portuguese
 *  sentence — the same thousandfold-misread class `useNum` exists for, one decimal place smaller.
 *  A probability read as a count is exactly the misreading this project has already been bitten by.
 *
 *  The formatter is memoised per language for the same reason `useNum`'s is: this renders inside a
 *  card that can be mounted for every parked tool call of a fan-out.
 */
export function useP(): (p: number) => string {
  const { lang } = useI18n();
  return useMemo(() => {
    const fmt = new Intl.NumberFormat(lang, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
    return (p: number) => fmt.format(p);
  }, [lang]);
}
